{
  "steps": [
    {
      "label": "Build home configuration",
      "argv": [
        "nix",
        "build",
        "--out-link",
        "<flake>/state/nix-manager/build/home",
        "--log-format",
        "internal-json",
        "--print-out-paths",
        "<flake>#homeConfigurations.user-test.activationPackage",
        "--show-trace"
      ],
      "cwd": "<flake>",
      "progress": true
    },
    {
      "label": "Select Home Manager generation",
      "argv": [
        "nix-env",
        "--profile",
        "<flake>/state/nix/profiles/home-manager",
        "--set",
        "<flake>/state/nix-manager/build/home"
      ],
      "cwd": "<flake>"
    },
    {
      "label": "Activate Home Manager",
      "argv": [
        "<flake>/state/nix-manager/build/home/activate",
        "--driver-version",
        "1"
      ],
      "cwd": "<flake>",
      "env": {
        "HOME_MANAGER_BACKUP_EXT": "hm-backup"
      }
    },
    {
      "label": "Keep 3 home generations",
      "argv": [
        "nix-env",
        "--profile",
        "<flake>/state/nix/profiles/home-manager",
        "--delete-generations",
        "+3"
      ],
      "cwd": "<flake>"
    },
    {
      "label": "Collect unreferenced store paths",
      "argv": [
        "nix-store",
        "--gc"
      ],
      "cwd": "<flake>"
    }
  ],
  "notes": [
    "Garbage collection deletes unreferenced store paths and older generations; these cannot be rolled back afterward."
  ]
}

{
  "steps": [
    {
      "label": "Roll back home configuration",
      "argv": [
        "home-manager",
        "switch",
        "--rollback"
      ],
      "cwd": "<flake>"
    },
    {
      "label": "Roll back system configuration",
      "argv": [
        "/run/wrappers/bin/pkexec",
        "/nix/store/216mr46yy8xspaydgapjhf4a21y643ji-bun-1.4.2/bin/bun",
        "<repo>/src/main.ts",
        "--privileged",
        "rollback"
      ],
      "cwd": "<flake>"
    }
  ],
  "notes": []
}

